.eski .ib.b{background:linear-gradient(135deg,#6b7c94,#99a5b5)}.eski .ib.o{background:linear-gradient(135deg,#6a7b92,#8e9bad)}
.eski .ib.g{background:linear-gradient(135deg,#4e5a6b,#6d7e95)}.eski .ib.p{background:linear-gradient(135deg,#97a3b3,#bbc3ce)}
/* üçlü kartlar */
