.eski .hk .cd{justify-self:start;font-size:20px;font-weight:800;color:#576477;background:#f2f3f5;border-radius:10px;padding:5px 14px}
.eski .lv{display:inline-block;font-weight:700;font-size:13px;padding:3px 12px;border-radius:999px;background:#e7eaee;color:#3e4856}
.eski .lv.y{background:#edeff2;color:#4b5767}
.eski .hk .none{padding:22px;font-weight:600}
.eski .pgart{display:flex;gap:14px;justify-content:center;align-items:center}
.eski .pgart svg{width:104px;height:104px;padding:12px;border-radius:24px;background:#ffffff;box-shadow:0 18px 40px #00000066}
.eski .pgart svg:nth-child(2){margin-top:34px}
/* sektör kartları */
.eski .sekw{background:linear-gradient(180deg,#e8ebef,#f2f3f5)}
.eski .sek{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.eski .sek a{position:relative;display:flex;flex-direction:column;gap:6px;padding:20px;background:#ffffff;border-radius:18px;box-shadow:0 8px 24px #59677b33;border:1px solid #e5e8ed;transition:transform .16s,box-shadow .16s}
.eski .sek a:hover{transform:translateY(-3px);box-shadow:0 14px 32px #59677b4d}
.eski .sek .ic{width:80px;height:80px;padding:11px;border-radius:22px;margin-bottom:8px;box-shadow:0 10px 22px #59677b40}
.eski .sek a:nth-child(1) .ic{background:linear-gradient(135deg,#6a7b92,#98a4b4)}
.eski .sek a:nth-child(2) .ic{background:linear-gradient(135deg,#67788f,#9ea9b9)}
.eski .sek a:nth-child(3) .ic{background:linear-gradient(135deg,#6b7c94,#a0abba)}
.eski .sek a:nth-child(4) .ic{background:linear-gradient(135deg,#97a3b3,#c1c8d2)}
.eski .sek a:nth-child(5) .ic{background:linear-gradient(135deg,#4e5a6b,#7b8aa0)}
.eski .sek a:nth-child(6) .ic{background:linear-gradient(135deg,#576477,#909daf)}
.eski .sek a:nth-child(7) .ic{background:linear-gradient(135deg,#6b7c94,#94a1b2)}
.eski .sek a:nth-child(8) .ic{background:linear-gradient(135deg,#73839a,#b2bbc7)}
.eski .sek b{font-size:18px;line-height:1.2;color:#3a4350;font-weight:800}
.eski .sek span{font-size:13.5px;line-height:1.4;color:#424c5b}.eski .sek em{font-style:normal}
.eski .sek a>svg:last-child{position:absolute;right:16px;top:16px;width:34px;height:34px;padding:8px;border-radius:50%;background:#f2f3f5;color:#6b7c94}
.eski .sek a:hover>svg:last-child{background:#6a7b92;color:#ffffff}
/* hata/sektör alt bandı */
.eski .ctaw{background:#f9f9fa;padding:36px 0}
.eski .cta2{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:28px;align-items:center;color:#2b3340;border-radius:18px;padding:28px 36px;background:#f5f6f8}
.eski .cta2 h2{font-size:28px;line-height:1.15;font-weight:800}.eski .cta2 p{color:#2b3340;margin-top:6px;max-width:560px}
@media(max-width:1060px){
 .eski .pgh h1{font-size:34px}
 .eski .three,.eski .fgrid{grid-template-columns:1fr 1fr}
 .eski .dpr,.eski .us,.eski .sss{grid-template-columns:1fr}
 .eski .sek{grid-template-columns:1fr 1fr}
 .eski .pgart{justify-content:flex-start}
 .eski .cta2{grid-template-columns:1fr}
}
@media(max-width:700px){
 .eski main>section{padding:34px 0}
 .eski .three,.eski .fgrid{grid-template-columns:1fr}
 .eski .sh h2,.eski .dpr h2,.eski .us h2{font-size:26px}
 .eski .dform{padding:20px}.eski .dform .frm,.eski .tool{grid-template-columns:1fr}
 .eski .dform .frm>div:nth-child(3){grid-column:auto}
 .eski .hk .r.h{display:none}
 .eski .hk .r{grid-template-columns:1fr;gap:6px;padding:16px 18px}
 .eski .hk .r:not(.h)>div:nth-child(2):before{content:"Anlamı: ";font-weight:700}
 .eski .hk .r:not(.h)>div:nth-child(4):before{content:"İlk kontrol: ";font-weight:700}
 .eski .cta2{padding:24px 20px}.eski .cta2 h2{font-size:24px}
 .eski .pgart svg{width:84px;height:84px}
}
@media(max-width:560px){
 .eski .sek{grid-template-columns:1fr}
 .eski .sek a{display:grid;grid-template-columns:72px 1fr;column-gap:14px;row-gap:2px;align-items:center;padding:14px 56px 14px 14px}
 .eski .sek .ic{grid-row:1/3;width:72px;height:72px;margin:0}
 .eski .sek a>svg:last-child{top:50%;transform:translateY(-50%)}
 .eski .big{font-size:26px}
}

